  public static func ==(lhs: Amoo_SetTargetAppRequest, rhs: Amoo_SetTargetAppRequest) -> Bool {
    if lhs.bundleID != rhs.bundleID {return false}
    if lhs.unknownFields != rhs.unknownFields {return false}
    return true
  }
}
